  Cube(n+" sign board",p+new Vector3(0,2.72f,-3.00f),new Vector3(2.25f,.48f,.13f),darkWood);Cube(n+" sign inset",p+new Vector3(0,2.72f,-3.09f),new Vector3(2.05f,.30f,.05f),inn?gold:accent);Lamp(p+new Vector3(-2.8f,0,-3.2f));
